#include "battery_time.h"

#include <stddef.h>

/**
 * @brief Empty the window (a restart): the next reading starts a new
 *        average, and the held current and both flags start again too.
 */
static void battime_clear(BatTime_Estimator *est)
{
    est->count     = 0U;
    est->next      = 0U;
    est->sum       = 0;
    est->have_held = 0U;
    est->draining  = 0U;
    est->filling   = 0U;
}

/**
 * @brief Stage 1: add one reading; once the window is full the oldest one
 *        drops out.
 */
static void battime_add(BatTime_Estimator *est, int16_t mA)
{
    if (est->count == BATTIME_WINDOW) {
        est->sum -= est->samples[est->next];    /* the oldest reading */
    } else {
        est->count++;
    }
    est->samples[est->next] = mA;
    est->sum += mA;
    est->next = (uint8_t)((est->next + 1U) % BATTIME_WINDOW);
}

/**
 * @brief Stage 1: the window's mean, rounded to the nearest mA (a half away
 *        from zero, so charging and discharging round alike). Never empty
 *        here.
 *
 * At most 120 int16 readings: |sum| <= 120 * 32768 = 3 932 160 fits a
 * 32-bit sum easily, and the mean of int16 values is an int16 again.
 */
static int16_t battime_mean(const BatTime_Estimator *est)
{
    const int32_t n = (int32_t)est->count;

    if (est->sum >= 0) {
        return (int16_t)((est->sum + n / 2) / n);
    }
    return (int16_t)(-((-est->sum + n / 2) / n));
}

/**
 * @brief Stage 2: move the held current.
 *
 * It takes the new average only when that is 5 % of it away, and at least
 * 10 mA (the first average after a restart is taken at once). 32-bit sums:
 * 5 % of 32768 mA is far inside the range.
 */
static void battime_hold_current(BatTime_Estimator *est, int16_t avg)
{
    int32_t diff = (int32_t)avg - est->held_mA;
    int32_t need = (int32_t)est->held_mA * BATTIME_HOLD_PERCENT / 100;

    if (diff < 0) {
        diff = -diff;
    }
    if (need < 0) {
        need = -need;
    }
    if (need < BATTIME_HOLD_MIN_MA) {
        need = BATTIME_HOLD_MIN_MA;
    }
    if (est->have_held == 0U || diff >= need) {
        est->held_mA   = avg;
        est->have_held = 1U;
    }
}

/**
 * @brief Stage 3: is the battery draining, or filling? Decided on the
 *        2-minute average.
 *
 * Draining starts at -10 mA and lasts until the average is back to 0 mA
 * or above; filling starts at +10 mA and lasts until 0 mA or below. The
 * gap stops an average near +/-10 mA from making the time come and go.
 * (The held current is not used here: it can stop 1-2 mA short of 0 and
 * would then keep a time on a battery that no longer drains.)
 */
static void battime_direction(BatTime_Estimator *est, int16_t avg)
{
    if (avg <= -BATTIME_DEADBAND_MA) {
        est->draining = 1U;
    } else if (avg >= 0) {
        est->draining = 0U;
    }
    if (avg >= BATTIME_DEADBAND_MA) {
        est->filling = 1U;
    } else if (avg <= 0) {
        est->filling = 0U;
    }
}

/**
 * @brief Minutes to move @p mAh at @p mA (mA >= 1), rounded to the nearest
 *        minute (a half rounds up), capped at BATTIME_MAX_MIN.
 *
 * 32-bit: 65535 mAh * 60 + 32768 / 2 = 3 948 484, far below 2^32, so no
 * capacity the gauge can report and no current from 1 mA can overflow.
 */
static uint16_t battime_minutes(uint32_t mAh, uint32_t mA)
{
    const uint32_t min = (mAh * 60U + mA / 2U) / mA;

    return (min > BATTIME_MAX_MIN) ? (uint16_t)BATTIME_MAX_MIN : (uint16_t)min;
}

/**
 * @brief Stages 1 to 3: restart on a charger change, settle, average (not
 *        a reading AverageCurrent stood in for), hold the current, then
 *        the rules of battery_time.h in order. Fills out->avg_mA, tte_min,
 *        ttf_min; the caller has set them to "no estimate" already.
 */
static void battime_estimate(BatTime_Estimator *est, const Battery_Snapshot_t *snap,
                             uint8_t chg, uint8_t complete, BatTime_Result *out)
{
    int16_t avg;

    /* Invalid reading (the gauge missed a poll): nothing is known about the
     * current now, so no time for this publish. The average is KEPT, so a
     * short gap does not throw away two minutes of readings; but a gauge
     * out for a whole window (2 min) leaves readings that say nothing about
     * now, so then it starts again. The publish still counts toward the
     * settling after a charger change, which is about the time since it. */
    if (snap == NULL || snap->valid != 1U) {
        if (est->missed < BATTIME_WINDOW) {
            est->missed++;
            if (est->missed == BATTIME_WINDOW) {
                battime_clear(est);
            }
        }
        if (est->settle > 0U) {
            est->settle--;
        }
        return;
    }
    est->missed = 0U;

    /* Charger plugged in or out, or a charge finishing: restart, and leave
     * out the next readings, which may still carry the old current. The
     * first valid reading only records the flag (nothing to compare with). */
    if (est->have_charging == 0U) {
        est->have_charging = 1U;
        est->charging      = chg;
    } else if (chg != est->charging) {
        est->charging = chg;
        battime_clear(est);
        est->settle = BATTIME_SETTLE_READINGS;
    }
    if (est->settle > 0U) {
        est->settle--;
        out->avg_mA = snap->current_now_mA;     /* nothing averaged yet: the reading itself */
        return;
    }

    /* Current() failed and AverageCurrent stands in: not averaged (it can
     * still carry the old current). The window as it is gives the result. */
    if (snap->current_now_ok == 1U) {
        battime_add(est, snap->current_now_mA);
    } else if (est->count == 0U) {
        out->avg_mA = snap->current_now_mA;     /* nothing averaged yet: the reading itself */
        return;
    }
    avg = battime_mean(est);
    out->avg_mA = avg;
    battime_hold_current(est, avg);
    battime_direction(est, avg);

    if (est->count < BATTIME_MIN_SAMPLES || snap->full_capacity_mAh == 0U) {
        return;     /* too few readings, or no capacity figure: both unknown */
    }

    /* Time to empty whenever the battery is draining, on the charger or
     * not: loud music can take more than the charger gives. The held
     * current is checked too, so the division is always by 1 mA or more. */
    if (est->draining == 1U && est->held_mA < 0) {
        out->tte_min = battime_minutes(snap->remaining_mAh,
                                       (uint32_t)(-(int32_t)est->held_mA));
    }

    if (chg == 1U) {
        if (snap->remaining_mAh >= snap->full_capacity_mAh) {
            out->ttf_min = 0U;                  /* full: nothing left to charge */
        } else if (est->filling == 1U && est->held_mA > 0) {
            out->ttf_min = battime_minutes((uint32_t)snap->full_capacity_mAh - snap->remaining_mAh,
                                           (uint32_t)est->held_mA);
        }
    } else if (complete != 0U) {
        out->ttf_min = 0U;                      /* the charger says the charge is done */
    }
}

/**
 * @brief The step a shown time moves in: 1 min under an hour, 5 min under
 *        10 hours, 15 min from 10 hours.
 */
static uint16_t battime_step(uint16_t minutes)
{
    if (minutes < 60U) {
        return BATTIME_STEP_UNDER_1H;
    }
    if (minutes < 600U) {
        return BATTIME_STEP_UNDER_10H;
    }
    return BATTIME_STEP_LONG;
}

/**
 * @brief @p minutes rounded to the nearest step (a half rounds up), never
 *        above the 99:59 cap (5999 rounds to 6000, which is capped).
 */
static uint16_t battime_round_to_step(uint16_t minutes)
{
    const uint32_t step    = battime_step(minutes);
    const uint32_t rounded = ((minutes + step / 2U) / step) * step;

    return (rounded > BATTIME_MAX_MIN) ? (uint16_t)BATTIME_MAX_MIN : (uint16_t)rounded;
}

/**
 * @brief Stage 4: what the screens show for one time.
 *
 * @param shown What they show now.
 * @param time  The new time from stage 3.
 * @return Unknown and 0 (full or empty) at once, and the first time after
 *         an unknown. Otherwise, with step = the step of @p time:
 *         - less than one and a half steps away: @p shown stays (without
 *           this margin a time halfway between two steps would flick
 *           between them every second);
 *         - one and a half to two and a half steps away: one step towards
 *           @p time (a steady countdown shows every step);
 *         - two and a half steps or more away: @p time rounded to its
 *           step (a big change of the time shows at once, not as several
 *           single steps one second apart).
 *         After either move the time is less than one and a half steps
 *         away, so the shown time then holds (except, rarely, when a
 *         step up crosses into a longer step, at 1 h or 10 h, or at the
 *         99:59 cap: then it moves once more a second later).
 */
static uint16_t battime_show(uint16_t shown, uint16_t time)
{
    uint32_t diff;
    uint32_t step;

    if (time == BATTIME_UNKNOWN) {
        return BATTIME_UNKNOWN;                 /* no estimate: --:-- at once */
    }
    if (time == 0U || shown == BATTIME_UNKNOWN) {
        return battime_round_to_step(time);     /* full or empty, or the first time: at once */
    }
    diff = (time > shown) ? (uint32_t)(time - shown) : (uint32_t)(shown - time);
    step = battime_step(time);
    if (2U * diff < 3U * step) {
        return shown;                           /* within one and a half steps: hold */
    }
    if (2U * diff < 5U * step) {                /* under two and a half steps: one step towards it */
        return battime_round_to_step((time > shown) ? (uint16_t)(shown + step)
                                                    : (uint16_t)(shown - step));
    }
    return battime_round_to_step(time);         /* far away: straight there */
}

/**
 * @brief Start empty: no readings, no charging flag yet, nothing shown.
 */
void BatTime_Init(BatTime_Estimator *est)
{
    uint8_t k;

    if (est == NULL) {
        return;
    }
    for (k = 0U; k < BATTIME_WINDOW; k++) {
        est->samples[k] = 0;
    }
    battime_clear(est);
    est->settle        = 0U;
    est->charging      = 0U;
    est->have_charging = 0U;
    est->missed        = 0U;
    est->held_mA       = 0;
    est->shown_tte     = BATTIME_UNKNOWN;
    est->shown_ttf     = BATTIME_UNKNOWN;
}

/**
 * @brief One publish: stages 1 to 3 (the average and the times), then
 *        stage 4 (the times as shown).
 */
void BatTime_Update(BatTime_Estimator *est, const Battery_Snapshot_t *snap,
                    uint8_t charging, uint8_t complete, BatTime_Result *out)
{
    if (out == NULL) {
        return;
    }
    out->avg_mA        = 0;
    out->tte_min       = BATTIME_UNKNOWN;
    out->ttf_min       = BATTIME_UNKNOWN;
    out->tte_shown_min = BATTIME_UNKNOWN;
    out->ttf_shown_min = BATTIME_UNKNOWN;
    if (est == NULL) {
        return;
    }

    battime_estimate(est, snap, (charging != 0U) ? 1U : 0U, complete, out);

    est->shown_tte     = battime_show(est->shown_tte, out->tte_min);
    est->shown_ttf     = battime_show(est->shown_ttf, out->ttf_min);
    out->tte_shown_min = est->shown_tte;
    out->ttf_shown_min = est->shown_ttf;
}
